python3 -c "
import subprocess, re
result = subprocess.run(['pdftotext', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
# Find page breaks (form feed characters)
pages = text.split('\f')
# Find which page contains 'Limitations' section
for i, page in enumerate(pages):
    if 'Limitations' in page and i < 12:
        # Check if this looks like the Limitations section header
        lines = page.strip().split('\n')
        for line in lines:
            if 'Limitation' in line:
                print(f'Page {i+1}: {line.strip()}')
                break

# Find which page has 'References' or bibliography start
for i, page in enumerate(pages):
    if 'References' in page and i < 15:
        lines = page.strip().split('\n')
        for line in lines:
            if 'References' in line:
                print(f'Page {i+1}: {line.strip()}')
                break

# Find appendix
for i, page in enumerate(pages):
    if 'Appendix' in page or '\\\\appendix' in page:
        lines = page.strip().split('\n')
        for line in lines:
            if 'Appendix' in line or 'appendix' in line.lower():
                print(f'Page {i+1}: {line.strip()}')
                break
print(f'Total pages: {len(pages)-1}')
"

